def is_subset_sum(set, n, sum):
    # Base case: if the sum is 0, a subset is found
    if sum == 0:
        return True
    # If no elements remain or the sum is negative, no subset can be found
    if n == 0 or sum < 0:
        return False
    # If the last element is greater than the sum, skip it
    if set[n - 1] > sum:
        return is_subset_sum(set, n - 1, sum)
    # Check if the subset is found by including or excluding the last element
    return is_subset_sum(set, n - 1, sum) or is_subset_sum(set, n - 1, sum - set[n - 1])
```
